def trouver_minimum(l: list, debut=0):
    if len(l) <= 2:
        return -1
    pos = len(l) // 2
    if l[pos+1] > l[pos] and l[pos-1] > l[pos]:
        return debut + pos
    elif l[pos] > l[pos+1]:
        return trouver_minimum(l[pos:], debut=debut + pos)
    else:
        return trouver_minimum(l[:pos+1], debut=debut)

def trouver_intervalle(fonction, a: int, b: int, precision: float):
    if fonction(a)*fonction(b) > 0:
        return -1
    if (b - a) < precision:
        return (a,b)
    else:
        pos = (a + b) / 2
        if fonction(a)*fonction(pos) <= 0:
            return trouver_intervalle(fonction, a, pos, precision)
        else:
            return trouver_intervalle(fonction, pos, b, precision)

def recherchedico(l, val, debut=0):
    if len(l) == 0:
        return -1
    pos = len(l) // 2
    if l[pos] == val:
        return debut + pos
    elif l[pos] > val:
        return recherchedico(l[:pos], val, debut=debut)
    else:
        return recherchedico(l[pos+1:], val, debut=debut+pos+1)

def posdico(l, val, debut=0):
    if len(l) == 0:
        return debut
    if len(l) ==1:
        #print("ici",val, debut)
        if val < l[0]:
            return debut
        elif val == l[0]:
            return debut
        else:
            return debut+1
    pos = len(l) // 2
    if l[pos] == val:
        return pos + debut
    elif l[pos] > val:
        return posdico(l[:pos], val, debut=debut)
    else:
        return posdico(l[pos+1:], val, debut=debut+pos+1)

def insert(l, val):
    if len(l) == 0:
        return [val]
    pos = posdico(l,val)
    #print(l, val, pos)
    return l[:pos]+[val]+l[pos:]

def delete(l, val):
    pos = recherchedico(l, val)
    if (pos == -1):
        return l
    else:
        return l[:pos] +l[pos+1:]
